fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    // If there are fewer than 2 elements, nothing to insert.
    if n <= 1 {
        return numbers;
    }

    // The resulting length is 2*n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, num) in numbers.into_iter().enumerate() {
        // Always push the next number
        result.push(num);
        // After every element except the last, insert the delimiter
        if i != n - 1 {
            result.push(delimiter);
        }
    }

    result
}

